/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, data=0;
  wire match, not_match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data), .match(match), .not_match(not_match));
  always #5 clk = ~clk;

  task send_group(input [5:0] bits);
    integer i;
    begin
      for (i=5; i>=0; i=i-1) begin
        data = bits[i];
        #10;
        "'$display("t=%0t data=%0b pstate? match=%0b not_match=%0b", $time, data, match, not_match);
      end
    end
  endtask

  initial begin
    #2; rst_n=0; #8; rst_n=1;
    // fail first group: 111111, then next group starts with 1 so should fail immediately, not act like first bit was 0
    send_group(6'"'b111111);
    send_group(6'b111111);
    send_group(6'b011100);
    #10; "'$finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

