/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, data=0;
  wire match, not_match;
  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data), .match(match), .not_match(not_match));
  always #5 clk = ~clk;

  task send_bits(input [11:0] bits);
    integer i;
    begin
      for (i=11; i>=0; i=i-1) begin
        data = bits[i];
        #1;
        "'$display("pre  t=%0t data=%0b pstate=%0d match=%0b not_match=%0b", $time, data, dut.pstate, match, not_match);
        #9;
        $display("post t=%0t data=%0b pstate=%0d match=%0b not_match=%0b", $time, data, dut.pstate, match, not_match);
      end
    end
  endtask

  initial begin
    #2; rst_n=0; #8; rst_n=1;
    // group1=111111 (fail), group2=111100 (should fail, but buggy sf6->s1 can falsely match)
    send_bits(12'"'b111111_111100);
    #10; "'$finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

